}

.container div button {
  /* styles for button */
}

/* Example: styling a heading */
h1 {
  color: blue;
}

/* Example: select any <section> that contains an <h2> */
section:has(h2) {
  background-color: lightblue;
}

/* Example: style a div when it contains a paragraph */
div:has(p) {
  background-color: lightblue;
  border: 2px solid blue;
}

/* Example: styling a list item when it contains a hovered link */
li:has(a:hover) {
    background-color: lightyellow;
    border-left: 3px solid orange;
}

